{"description":"Select candidate by minimum threshold margin","cmd":"cd /app && python3 - <<'PY'
def load(path):
    d={}
    for line in open(path):
        p=line.strip().split()
        d[p[0]]=tuple(map(int,p[2:5]))
    return d
paper=load('candidates/g2_paper_results.txt'); stone=load('candidates/g2_stone_top_results.txt'); vamp=load('candidates/g2_vampire_top_results.txt'); snake=load('candidates/g2_snake_top_results.txt'); g2=load('candidates/g2_g2-clear_top_results.txt')
req={'paper':75,'stone':75,'vamp':75,'snake':33,'g2':33}
rows=[]
for f in stone:
    vals={'paper':paper[f][0],'stone':stone[f][0],'vamp':vamp[f][0],'snake':snake[f][0],'g2':g2[f][0]}
    if all(vals[k]>=req[k] for k in req):
        margin=min((vals[k]-req[k]) for k in req)
        rows.append((margin, vals['paper'], vals['stone'], vals['vampire' if False else 'vamp'], vals['snake'], vals['g2'], f))
rows.sort(reverse=True)
for r in rows[:20]:
    print('margin',r[0],'p',r[1],'s',r[2],'v',r[3],'sn',r[4],'g',r[5],r[6])
